<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$uid=learning_user_id();$s=learning_pdo()->prepare("SELECT l.id,l.title,m.title module_title,c.slug FROM learning_bookmarks b JOIN learning_lessons l ON l.id=b.lesson_id JOIN learning_modules m ON m.id=l.module_id JOIN learning_courses c ON c.id=m.course_id WHERE b.user_id=? ORDER BY b.created_at DESC");$s->execute([$uid]);$rows=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bookmarks</title><style>body{margin:0;background:#080a10;color:#fff;font-family:Inter,system-ui}.wrap{max-width:850px;margin:auto;padding:30px 18px}.row{padding:14px;border:1px solid #fff1;border-radius:12px;background:#10151e;margin:8px 0}.row a{color:#a78bfa;text-decoration:none;font-size:10px}.small{display:block;color:#788398;font-size:8px;margin-top:4px}</style></head><body><div class=wrap><a href="/creator-ai/learning/" style="color:#a78bfa;font-size:8px">← Learning Hub</a><h1>🔖 Bookmarks</h1><?php if(!$rows):?><p class=small>No bookmarks yet.</p><?php endif;?><?php foreach($rows as $r):?><div class=row><a href="/creator-ai/learning/<?=eh($r['slug'])?>/lesson.php?id=<?=$r['id']?>"><?=eh($r['title'])?></a><span class=small><?=eh($r['module_title'])?></span></div><?php endforeach;?></div></body></html>